enum Node {
    case file(name: String, bytes: Int)
    indirect case dir(name: String, children: [Node])
}

func size(_ node: Node) -> Int {
    switch node {
    case .file(_, let bytes): return bytes
    case .dir(_, let children): return children.reduce(0) { $0 + size($1) }
    }
}

