protocol Component { func size() -> Int }

struct File: Component { let bytes: Int; func size() -> Int { bytes } }

final class Dir: Component {
    private(set) var children: [any Component] = []
    func add(_ child: any Component) { children.append(child) }
    func size() -> Int { children.reduce(0) { $0 + $1.size() } }
}
